  "quiz": [
    {
      "id": "q1",
      "q": "二十年前因冬至时刻出错被治罪、死在狱中的老监正是谁？",
      "options": [
        {
          "key": "A",
          "text": "甄鸿渐"
        },
        {
          "key": "B",
          "text": "沈怀瑾"
        },
        {
          "key": "C",
          "text": "周明远"
        },
        {
          "key": "D",
          "text": "刘更生"
        }
      ],
      "answer": "B",
      "clue": "ar_2",
      "explain": "星图库的卷宗记着：永熙元年冬至，监正沈怀瑾误报冬至时刻，欺君误国，下狱。"
    },
    {
      "id": "q2",
      "q": "当年被人换页、用来坐实老监正「失候」之罪的是哪一本册子？",
      "options": [
        {
          "key": "A",
          "text": "值夜簿"
        },
        {
          "key": "B",
          "text": "星表"
        },
        {
          "key": "C",
          "text": "刻簿"
        },
        {
          "key": "D",
          "text": "历稿"
        }
      ],
      "answer": "C",
      "clue": "ar_3",
      "explain": "永熙元年冬至夜的三页刻簿墨色一致、署名齐全，成了定罪的依据；真簿的原页却藏在刘更生的墙缝里。"
    },
    {
      "id": "q3",
      "q": "当年奉甄鸿渐之命誊抄那几页假刻簿的是谁？",
      "options": [
        {
          "key": "A",
          "text": "魏素心"
        },
        {
          "key": "B",
          "text": "刘更生"
        },
        {
          "key": "C",
          "text": "张观澜"
        },
        {
          "key": "D",
          "text": "周明远"
        }
      ],
      "answer": "B",
      "clue": "li_4",
      "explain": "刘更生砖后的黄纸里附着一张字条：奉甄副监之命，重抄冬至夜刻簿三页，更生记。"
    },
    {
      "id": "q4",
      "q": "魏素心当年在那几页刻簿的页尾做了什么？",
      "options": [
        {
          "key": "A",
          "text": "签押作证"
        },
        {
          "key": "B",
          "text": "当面揭发"
        },
        {
          "key": "C",
          "text": "烧毁抄本"
        },
        {
          "key": "D",
          "text": "出走京城"
        }
      ],
      "answer": "A",
      "clue": "ar_3",
      "explain": "刻簿正本的页尾有三个署名：记录刘更生，见证魏素心，核定甄鸿渐。"
    },
    {
      "id": "q5",
      "q": "九年前向甄鸿渐呈文、说刻簿前后墨色不一的是谁？",
      "options": [
        {
          "key": "A",
          "text": "刘更生"
        },
        {
          "key": "B",
          "text": "周明远"
        },
        {
          "key": "C",
          "text": "欧小满"
        },
        {
          "key": "D",
          "text": "大安"
        }
      ],
      "answer": "B",
      "clue": "ar_4",
      "explain": "星图库铁箱里的呈文署周明远，钦天监主簿，写着刻簿冬至夜三页前后墨色不一，末页朱批：知道了。"
    },
    {
      "id": "q6",
      "q": "周明远与蓉晚晴是什么关系？",
      "options": [
        {
          "key": "A",
          "text": "师徒"
        },
        {
          "key": "B",
          "text": "夫妻"
        },
        {
          "key": "C",
          "text": "兄妹"
        },
        {
          "key": "D",
          "text": "同乡"
        }
      ],
      "answer": "B",
      "clue": "ro_4",
      "explain": "蓉晚晴木匣里的病案署尚药局蓉氏记，匣中小木牌写着亡夫周公明远之位。"
    }
  ],
